-- 016_import_marg_manufacturer_master.sql
-- Imports 657 deduplicated pharmaceutical manufacturers from Marg ERP export (MANUFACTER ,COMPANY MASTER.XLS)

DO $$
DECLARE
  org_rec RECORD;
  dup_rec RECORD;
  keep_id uuid;
BEGIN
  FOR org_rec IN SELECT id FROM public.organizations LOOP
    -- 1. Clean up known placeholder/junk entries
    DELETE FROM public.manufacturers 
    WHERE organization_id = org_rec.id 
      AND (name IN ('**', '*Not applicable', '0', '1', 'Z----') 
           OR name LIKE '*UN-DEFINED%' 
           OR name LIKE 'No..%' 
           OR name LIKE 'Page%');

    -- 2. Deduplicate existing manufacturers with matching case-insensitive names
    FOR dup_rec IN (
      SELECT LOWER(TRIM(name)) AS norm_name, COUNT(*)
      FROM public.manufacturers
      WHERE organization_id = org_rec.id
      GROUP BY LOWER(TRIM(name))
      HAVING COUNT(*) > 1
    ) LOOP
      -- Find primary ID to keep (prefer one linked to items)
      SELECT m.id INTO keep_id
      FROM public.manufacturers m
      LEFT JOIN public.items i ON i.manufacturer_id = m.id
      WHERE m.organization_id = org_rec.id AND LOWER(TRIM(m.name)) = dup_rec.norm_name
      GROUP BY m.id
      ORDER BY COUNT(i.id) DESC, m.created_at ASC
      LIMIT 1;

      -- Update items pointing to duplicates to point to keep_id
      UPDATE public.items
      SET manufacturer_id = keep_id
      WHERE organization_id = org_rec.id
        AND manufacturer_id IN (
          SELECT id FROM public.manufacturers
          WHERE organization_id = org_rec.id AND LOWER(TRIM(name)) = dup_rec.norm_name AND id != keep_id
        );

      -- Delete remaining duplicate rows
      DELETE FROM public.manufacturers
      WHERE organization_id = org_rec.id
        AND LOWER(TRIM(name)) = dup_rec.norm_name
        AND id != keep_id;
    END LOOP;

  END LOOP;
END $$;
